use vstd::prelude::*;

verus! {
    // classify days past into one of three categories:
    // "delicious"  if days_past <= 0
    // "safe"       if 0 < days_past <= x
    // "dangerous"  if days_past > x
    //
    // days_past is computed as (b as i32) - (a as i32) to avoid i8 overflow.
    fn determine_food_safety(x: i8, a: i8, b: i8) -> &'static str
        requires
            // threshold must be non-negative
            x >= 0,
        ensures
            // if days_past <= 0, we return "delicious"
            ((b as i32 - a as i32) <= 0 && result == "delicious") &&
            // if 0 < days_past <= x, we return "safe"
            ((b as i32 - a as i32) > 0 ==> (b as i32 - a as i32) <= (x as i32) && (result == "safe")) &&
            // if days_past > x, we return "dangerous"
            ((b as i32 - a as i32) > (x as i32) ==> result == "dangerous")
    {
        let days: i32 = (b as i32) - (a as i32);
        if days <= 0 {
            "delicious"
        } else if days <= (x as i32) {
            "safe"
        } else {
            "dangerous"
        }
    }
}

